+}
+
+it.each([
+  ["a plain row", "stored-plain", {}],
+  [
+    "a retained producer row",
+    "cron-direct-delivery:v1:stored",
+    {
+      completionRetention: {
+        idPrefix: "cron-direct-delivery:v1:",
+        maxAgeMs: 86_400_000,
